module.exports = {
  target: 'node', // 针对Node环境打包
  entry: './src/server.js',
  output: {
    filename: 'server.js',
    libraryTarget: 'commonjs2',
  },
  externals: [require('webpack-node-externals')()], // 剥离node_modules
};

// 客户端打包配置（webpack.client.js）
module.exports = {
  target: 'web',
  entry: './src/client.js',
  output: {
    filename: 'client.[contenthash].js',
  },
  // 其他优化配置（代码分割、压缩等）
