        keepClosingSlash: true,
        minifyJS: true,
        minifyCSS: true,
        minifyURLs: true,
      }
    }),
    new webpack.ProgressPlugin(),
    // 仅在需要分析时启用
    // new BundleAnalyzerPlugin()
  ],
  cache: {
    type: 'filesystem',
    buildDependencies: {
      config: [__filename]
    }
  },
  infrastructureLogging: {
    level: 'info'
  }
};
```

