  const dynamic = {
    content,
    time: new Date().toISOString()
  };

  // 1. 往列表头部添加动态
  await redis.lpush(dynamicKey, JSON.stringify(dynamic));
  // 2. 限制列表长度为10（只保留最新10条，超出的自动删除）
  await redis.ltrim(dynamicKey, 0, 9); // 0-9共10条

  ctx.body = { code: 200, msg: '动态添加成功' };
});

/**
 * 接口2：GET /dynamic/list/:userId
