  const { userId } = ctx.params;
  const dynamicKey = `dynamic:${userId}`;

  // lrange：获取列表所有元素（0到-1表示全部）
  const dynamicList = await redis.lrange(dynamicKey, 0, -1);
  const formatList = dynamicList.map(item => JSON.parse(item));

  ctx.body = {
    code: 200,
    data: formatList
  };
