  const { userId1, userId2 } = ctx.params;
  const key1 = `friend:${userId1}`;
  const key2 = `friend:${userId2}`;

  // sinter：求两个集合的交集（共同好友）
  const commonFriends = await redis.sinter(key1, key2);

  ctx.body = {
    code: 200,
    data: {
      userId1,
      userId2,
